     1→/**
     2→ * @module ConversationSessionContext
     3→ *
     4→ * Glue layer that connects the Conversation Policy Engine and the
     5→ * Conversation State Engine to a single OpenAI Realtime session.
     6→ *
     7→ * ## Purpose
     8→ * Owns one `ConversationStateBundle` and one `ConversationPolicyBuilder`
     9→ * for the lifetime of a call.  Provides:
    10→ *
    11→ * 1. `buildInstruction()` — merges the static policy instruction with a live
    12→ *    dynamic state section so the AI always knows its current stage, facts,
    13→ *    objections, and its immediate next goal.
    14→ *
    15→ * 2. `onAgentTurnCompleted(transcript)` — auto-dispatches the appropriate
    16→ *    signal after every agent response and returns the new instruction string
    17→ *    only when the conversation state actually changed (avoiding no-op updates).
    18→ *
    19→ * 3. `onCustomerInterrupted()` — records an interruption in the state machine.
    20→ *
    21→ * 4. `dispatchSignal(signal)` — pass-through for callers to inject any signal
    22→ *    (objections, pain points, qualification data, etc.) at any time.
    23→ *
    24→ * ## Rules
    25→ * - No OpenAI SDK imports.
    26→ * - No Exotel imports.
    27→ * - No Transport or Audio Engine imports.
    28→ * - Pure integration between Policy Engine and State Engine.
    29→ *
    30→ * ## Ownership
    31→ * Created by `OpenAIRealtimeProvider.openSession()` when a `policyContext`
    32→ * is provided.  Stored inside `OpenAIRealtimeSession` and consulted after
    33→ * every server-side event that represents a completed agent turn or customer
    34→ * interruption.
    35→ */
    36→
    37→import {
    38→  ConversationPolicyBuilder,
    39→  SalesConversationPolicy,
    40→} from '../../conversation/index.js';
    41→import type { PolicyConversationContext } from '../../conversation/index.js';
    42→
    43→import {
    44→  ConversationStateFactory,
    45→  ConversationStage,
    46→  Signals,
    47→  STAGE_METADATA,
    48→} from '../../conversation-state/index.js';
    49→import type {
    50→  ConversationStateBundle,
    51→  ConversationSignal,
    52→  ConversationState,
    53→} from '../../conversation-state/index.js';
    54→
    55→// ─── Dynamic State Renderer ───────────────────────────────────────────────────
    56→
    57→/**
    58→ * Renders the live conversation state as a formatted instruction section.
    59→ * Appended to the base policy instruction so OpenAI always has an up-to-date
    60→ * view of stage, facts, objections, and next goal.
    61→ */
    62→function renderDynamicStateSection(state: ConversationState): string {
    63→  const now = Date.now();
    64→  const ts = new Date(now).toISOString().slice(11, 19); // HH:MM:SS
    65→  const mem = state.memory;
    66→  const prog = state.progress;
    67→
    68→  const bar = '─'.repeat(60);
    69→
    70→  // ── Stage info ──────────────────────────────────────────────────────────────
    71→  const stageLabel = STAGE_METADATA[state.currentStage].label;
    72→  const prevLabel = state.previousStage
    73→    ? STAGE_METADATA[state.previousStage].label
    74→    : 'none';
    75→  const historyStr = state.stageHistory
    76→    .map((s) => STAGE_METADATA[s].label)
    77→    .join(' → ');
    78→  const timeInStage = Math.round(state.timeInCurrentStage(now) / 1000);
    79→
    80→  // ── Memory section ──────────────────────────────────────────────────────────
    81→  const memLines: string[] = [];
    82→  if (mem.customerName) memLines.push(`  • Name:     ${mem.customerName}`);
    83→  if (mem.company) memLines.push(`  • Company:  ${mem.company}`);
    84→  if (mem.intent) memLines.push(`  • Intent:   ${mem.intent}`);
    85→  if (mem.painPoints.length > 0) {
    86→    memLines.push(`  • Pain Points:`);
    87→    mem.painPoints.forEach((p) => memLines.push(`      – ${p}`));
    88→  }
    89→  if (mem.budget) memLines.push(`  • Budget:   ${mem.budget}`);
    90→  if (mem.timeline) memLines.push(`  • Timeline: ${mem.timeline}`);
    91→  if (mem.isDecisionMaker !== undefined) {
    92→    memLines.push(`  • Decision Maker: ${mem.isDecisionMaker ? 'Yes' : 'No'}`);
    93→  }
    94→  const knownFacts =
    95→    memLines.length > 0 ? memLines.join('\n') : '  (nothing captured yet)';
    96→
    97→  // ── DO NOT ASK AGAIN block ──────────────────────────────────────────────────
    98→  const doNotAskLines: string[] = [];
    99→  if (mem.customerName) doNotAskLines.push(`  • Their name (it's ${mem.customerName})`);
   100→  if (mem.company) doNotAskLines.push(`  • Their company (it's ${mem.company})`);
   101→  if (mem.intent) doNotAskLines.push(`  • Their intent (already stated)`);
   102→  if (mem.painPoints.length > 0) {
   103→    mem.painPoints.forEach((p) => doNotAskLines.push(`  • Pain point already given: "${p}"`));
   104→  }
   105→  if (mem.budget) doNotAskLines.push(`  • Their budget (it's ${mem.budget})`);
   106→  if (mem.timeline) doNotAskLines.push(`  • Their timeline (it's ${mem.timeline})`);
   107→  if (mem.isDecisionMaker !== undefined) {
   108→    doNotAskLines.push(
   109→      `  • Whether they're the decision-maker (answer: ${mem.isDecisionMaker ? 'Yes' : 'No'})`
   110→    );
   111→  }
   112→  const doNotAskSection =
   113→    doNotAskLines.length > 0
   114→      ? `⛔ DO NOT ASK AGAIN — the caller already provided:\n${doNotAskLines.join('\n')}`
   115→      : '  (no facts captured yet — nothing to guard)';
   116→
   117→  // ── Objections ──────────────────────────────────────────────────────────────
   118→  const unresolvedObjLines = mem.unresolvedObjections.map(
   119→    (o) => `  • [UNRESOLVED] ${o.topic}${o.verbatim ? ` — "${o.verbatim}"` : ''}`
   120→  );
   121→  const resolvedObjLines = mem.objections
   122→    .filter((o) => o.resolved)
   123→    .map((o) => `  • [resolved]   ${o.topic}`);
   124→  const objSection =
   125→    [...unresolvedObjLines, ...resolvedObjLines].join('\n') ||
   126→    '  none';
   127→
   128→  // ── Commitments ─────────────────────────────────────────────────────────────
   129→  const commitSection =
   130→    mem.commitments.length > 0
   131→      ? mem.commitments.map((c) => `  • ${c.description}`).join('\n')
   132→      : '  none';
   133→
   134→  // ── Next action ─────────────────────────────────────────────────────────────
   135→  const nextAction = mem.nextAction ?? 'not yet determined';
   136→
   137→  // ── Progress ────────────────────────────────────────────────────────────────
   138→  const turnsTotal = prog.totalAgentTurns;
   139→  const turnsStage = state.turnsInCurrentStage;
   140→  const questionsStage = state.questionsInCurrentStage;
   141→
   142→  // ── Build section ───────────────────────────────────────────────────────────
   143→  return [
   144→    `\n${bar}`,
   145→    `## LIVE CONVERSATION STATE  [updated ${ts}]`,
   146→    bar,
   147→    `Current Stage:    ${stageLabel}`,
   148→    `Previous Stage:   ${prevLabel}`,
   149→    `Stage History:    ${historyStr}`,
   150→    `Time in Stage:    ${timeInStage}s`,
   151→    `Agent Turns:      ${turnsTotal} total, ${turnsStage} this stage`,
   152→    `Questions Asked:  ${questionsStage} this stage`,
   153→    `Min Turns Met:    ${state.hasMetMinimumTurns ? 'Yes' : 'No'}`,
   154→    ``,
   155→    `Known Customer Facts:`,
   156→    knownFacts,
   157→    ``,
   158→    doNotAskSection,
   159→    ``,
   160→    `Objections:`,
   161→    objSection,
   162→    ``,
   163→    `Commitments:`,
   164→    commitSection,
   165→    ``,
   166→    `Agreed Next Action: ${nextAction}`,
   167→    ``,
   168→    `## YOUR IMMEDIATE NEXT GOAL`,
   169→    bar,
   170→    _renderNextGoal(state),
   171→    bar,
   172→  ].join('\n');
   173→}
   174→
   175→function _renderNextGoal(state: ConversationState): string {
   176→  const stage = state.currentStage;
   177→  const mem = state.memory;
   178→
   179→  switch (stage) {
   180→    case ConversationStage.GREETING:
   181→      return 'Greet the caller warmly, introduce yourself, and ask one open question to break the ice.';
   182→
   183→    case ConversationStage.RAPPORT:
   184→      return 'Build a genuine human connection. Show interest in the caller before any business discussion.';
   185→
   186→    case ConversationStage.DISCOVERY:
   187→      return mem.painPoints.length === 0
   188→        ? 'Ask open-ended questions to understand the caller\'s current challenges. Do NOT pitch yet.'
   189→        : `You have identified ${mem.painPoints.length} pain point(s). Continue exploring or advance to Qualification when ready.`;
   190→
   191→    case ConversationStage.QUALIFICATION:
   192→      const missing: string[] = [];
   193→      if (mem.isDecisionMaker === undefined) missing.push('decision-making authority');
   194→      if (!mem.budget) missing.push('budget');
   195→      if (!mem.timeline) missing.push('timeline');
   196→      return missing.length > 0
   197→        ? `Qualify the caller — still need: ${missing.join(', ')}.`
   198→        : 'Qualification complete — you may advance to Presentation.';
   199→
   200→    case ConversationStage.PRESENTATION:
   201→      return 'Present the solution that directly addresses the pain points you discovered. Keep it concise and tied to their specific needs.';
   202→
   203→    case ConversationStage.OBJECTION_HANDLING:
   204→      const unresolved = mem.unresolvedObjections;
   205→      return unresolved.length > 0
   206→        ? `Address the objection: "${unresolved[0].topic}". Acknowledge → reframe → ask if resolved.`
   207→        : 'All objections resolved — advance to Closing or return to Presentation.';
   208→
   209→    case ConversationStage.CLOSING:
   210→      return !mem.nextAction
   211→        ? 'Summarise the conversation and propose a concrete next step (e.g. demo date, follow-up call).'
   212→        : `Confirm the agreed next step: "${mem.nextAction}" and thank the caller.`;
   213→
   214→    case ConversationStage.CALL_COMPLETED:
   215→      return 'The conversation has ended. Wrap up gracefully.';
   216→
   217→    default:
   218→      return 'Continue the conversation following the sales funnel.';
   219→  }
   220→}
   221→
   222→// ─── ConversationSessionContext ───────────────────────────────────────────────
   223→
   224→export interface ConversationSessionContextOptions {
   225→  /** The policy context for this session. */
   226→  readonly policyContext: PolicyConversationContext;
   227→  /**
   228→   * Optional pre-loaded caller memory (e.g. from CRM before the call starts).
   229→   */
   230→  readonly preloadedMemory?: {
   231→    customerName?: string;
   232→    company?: string;
   233→    intent?: string;
   234→    painPoints?: string[];
   235→    isDecisionMaker?: boolean;
   236→    budget?: string;
   237→    timeline?: string;
   238→  };
   239→}
   240→
   241→/**
   242→ * Result returned by `onAgentTurnCompleted()` and `dispatchSignal()`.
   243→ */
   244→export interface StateUpdateResult {
   245→  /** Whether the conversation state changed as a result of the signal. */
   246→  readonly stateChanged: boolean;
   247→  /** The newly generated instruction, or null if no update is needed. */
   248→  readonly updatedInstruction: string | null;
   249→  /** The current stage label after the update. */
   250→  readonly currentStageLabel: string;
   251→}
   252→
   253→/**
   254→ * Connects the Policy Engine and State Engine to one OpenAI Realtime session.
   255→ */
   256→export class ConversationSessionContext {
   257→  private readonly _policyContext: PolicyConversationContext;
   258→  private readonly _builder: ConversationPolicyBuilder;
   259→  private readonly _bundle: ConversationStateBundle;
   260→
   261→  /** Snapshot of the previous state — used to detect changes. */
   262→  private _lastStage: ConversationStage;
   263→  /** Tracks whether the current response is being interrupted. */
   264→  private _responseInProgress = false;
   265→  /**
   266→   * Character count of the most recently generated instruction string.
   267→   * Updated by `buildInitialInstruction()` and `_buildResult()`.
   268→   * Exposed as a read-only getter for diagnostics — no behaviour change.
   269→   */
   270→  private _lastInstructionSizeChars = 0;
   271→
   272→  constructor(options: ConversationSessionContextOptions) {
   273→    this._policyContext = options.policyContext;
   274→    this._builder = new ConversationPolicyBuilder(new SalesConversationPolicy());
   275→
   276→    this._bundle = ConversationStateFactory.create({
   277→      preloadedMemory: options.preloadedMemory ?? {
   278→        customerName: options.policyContext.caller?.firstName,
   279→        company: options.policyContext.caller?.company,
   280→      },
   281→    });
   282→
   283→    this._lastStage = this._bundle.machine.currentStage;
   284→  }
   285→
   286→  // ─── Public API ─────────────────────────────────────────────────────────────
   287→
   288→  /**
   289→   * Generates the full initial system instruction for this session.
   290→   * Call once at session creation time and pass the result to OpenAI.
   291→   */
   292→  buildInitialInstruction(): string {
   293→    const baseInstruction = this._builder.build(this._policyContext);
   294→    const state = this._bundle.machine.getState();
   295→    const full = baseInstruction + renderDynamicStateSection(state);
   296→    this._lastInstructionSizeChars = full.length;
   297→    return full;
   298→  }
   299→
   300→  /**
   301→   * Character count of the last instruction string sent to OpenAI.
   302→   * Updated whenever `buildInitialInstruction()` is called or a state change
   303→   * triggers a new instruction via `_buildResult()`.
   304→   * Read by diagnostics — read-only, no behaviour change.
   305→   */
   306→  get lastInstructionSizeChars(): number {
   307→    return this._lastInstructionSizeChars;
   308→  }
   309→
   310→  /**
   311→   * Called after every completed agent response turn.
   312→   *
   313→   * Automatically:
   314→   * - Records the agent turn in the state machine.
   315→   * - Detects whether the agent's transcript contained a question.
   316→   * - Evaluates whether the stage should advance.
   317→   * - Returns a new instruction if state changed, or null if unchanged.
   318→   *
   319→   * @param transcript  The completed agent audio transcript (optional).
   320→   */
   321→  onAgentTurnCompleted(transcript?: string): StateUpdateResult {
   322→    this._responseInProgress = false;
   323→    const containedQuestion = transcript
   324→      ? /\?/.test(transcript)
   325→      : false;
   326→
   327→    const stageBeforeDispatch = this._bundle.machine.currentStage;
   328→
   329→    // Record the agent turn
   330→    let state = this._bundle.machine.dispatch(
   331→      Signals.agentTurnCompleted(containedQuestion)
   332→    );
   333→
   334→    // Ask the evaluator whether we should advance stage
   335→    const recommendation = this._bundle.evaluator.evaluate(state);
   336→    if (recommendation.shouldAdvanceStage) {
   337→      state = this._bundle.machine.dispatch(Signals.advanceStage());
   338→    }
   339→
   340→    return this._buildResult(stageBeforeDispatch, state);
   341→  }
   342→
   343→  /**
   344→   * Called when the server VAD detects customer speech while the agent
   345→   * is responding — this is a barge-in / interruption.
   346→   */
   347→  onCustomerInterrupted(): StateUpdateResult {
   348→    const stageBeforeDispatch = this._bundle.machine.currentStage;
   349→    this._responseInProgress = true;
   350→
   351→    const state = this._bundle.machine.dispatch(
   352→      Signals.customerInterrupted()
   353→    );
   354→
   355→    return this._buildResult(stageBeforeDispatch, state);
   356→  }
   357→
   358→  /**
   359→   * Dispatches any signal directly to the state machine.
   360→   * Use this to inject objections, pain points, qualification data, etc.
   361→   * Returns an updated instruction if the state changed.
   362→   */
   363→  dispatchSignal(signal: ConversationSignal): StateUpdateResult {
   364→    const stageBeforeDispatch = this._bundle.machine.currentStage;
   365→    const state = this._bundle.machine.dispatch(signal);
   366→    return this._buildResult(stageBeforeDispatch, state);
   367→  }
   368→
   369→  /**
   370→   * Returns the live `ConversationStateBundle` for direct access.
   371→   * Useful for callers that need to read memory or progress directly.
   372→   */
   373→  get bundle(): Readonly<ConversationStateBundle> {
   374→    return this._bundle;
   375→  }
   376→
   377→  /**
   378→   * Returns the current state snapshot.
   379→   */
   380→  getState(): ConversationState {
   381→    return this._bundle.machine.getState();
   382→  }
   383→
   384→  // ─── Private Helpers ────────────────────────────────────────────────────────
   385→
   386→  private _buildResult(
   387→    stageBeforeDispatch: ConversationStage,
   388→    state: ConversationState
   389→  ): StateUpdateResult {
   390→    const stageChanged = state.currentStage !== stageBeforeDispatch;
   391→    const memChanged = state.currentStage !== this._lastStage;
   392→
   393→    if (stageChanged) {
   394→      this._lastStage = state.currentStage;
   395→    }
   396→
   397→    // Regenerate instruction on any stage change or when memory is updated
   398→    const stateChanged = stageChanged || memChanged;
   399→    let updatedInstruction: string | null = null;
   400→    if (stateChanged) {
   401→      updatedInstruction = this._builder.build(this._policyContext) + renderDynamicStateSection(state);
   402→      // Track size for diagnostics — no behaviour change
   403→      this._lastInstructionSizeChars = updatedInstruction.length;
   404→    }
   405→
   406→    return {
   407→      stateChanged,
   408→      updatedInstruction,
   409→      currentStageLabel: STAGE_METADATA[state.currentStage].label,
   410→    };
   411→  }
   412→}
   413→

