     1→/**
     2→ * @module ConversationStateMachine
     3→ *
     4→ * Manages conversation stage transitions, enforcing the allowed-transition
     5→ * graph defined in ConversationStage and updating progress metrics.
     6→ *
     7→ * ## Purpose
     8→ * The single authoritative controller for conversation progression.  All
     9→ * stage changes flow through `dispatch()`.  Consumers never mutate stage
    10→ * directly.
    11→ *
    12→ * ## Guarantees
    13→ * - Transitions are validated against `ALLOWED_TRANSITIONS` before applying.
    14→ * - Progress and memory are updated atomically with state transitions.
    15→ * - Every transition is appended to an immutable audit log.
    16→ * - Terminal stages reject all further transitions gracefully.
    17→ *
    18→ * ## No AI imports
    19→ * Pure state machine — no OpenAI, Exotel, or prompt logic.
    20→ */
    21→
    22→import {
    23→  ConversationStage,
    24→  isTransitionAllowed,
    25→  isTerminalStage,
    26→  FUNNEL_ORDER,
    27→} from './ConversationStage.js';
    28→import type { ConversationSignal } from './ConversationSignals.js';
    29→import { ConversationState } from './ConversationState.js';
    30→import type { ConversationMemory } from './ConversationMemory.js';
    31→import type { ConversationProgress } from './ConversationProgress.js';
    32→
    33→// ─── Transition Record ────────────────────────────────────────────────────────
    34→
    35→export interface TransitionRecord {
    36→  readonly from: ConversationStage;
    37→  readonly to: ConversationStage;
    38→  readonly signal: ConversationSignal;
    39→  readonly occurredAt: number;
    40→}
    41→
    42→// ─── Transition Error ─────────────────────────────────────────────────────────
    43→
    44→export class TransitionError extends Error {
    45→  constructor(
    46→    from: ConversationStage,
    47→    to: ConversationStage,
    48→    reason: string
    49→  ) {
    50→    super(`Invalid transition ${from} → ${to}: ${reason}`);
    51→    this.name = 'TransitionError';
    52→  }
    53→}
    54→
    55→// ─── ConversationStateMachine ─────────────────────────────────────────────────
    56→
    57→export class ConversationStateMachine {
    58→  private _currentStage: ConversationStage;
    59→  private _previousStage: ConversationStage | null = null;
    60→  private _stageHistory: ConversationStage[] = [];
    61→  private _stageEnteredAt: number;
    62→  private readonly _transitionLog: TransitionRecord[] = [];
    63→
    64→  private readonly _memory: ConversationMemory;
    65→  private readonly _progress: ConversationProgress;
    66→
    67→  constructor(
    68→    initialStage: ConversationStage,
    69→    memory: ConversationMemory,
    70→    progress: ConversationProgress,
    71→    now: number = Date.now()
    72→  ) {
    73→    this._currentStage = initialStage;
    74→    this._stageHistory.push(initialStage);
    75→    this._stageEnteredAt = now;
    76→    this._memory = memory;
    77→    this._progress = progress;
    78→    this._progress.enterStage(initialStage, now);
    79→  }
    80→
    81→  // ─── Public API ─────────────────────────────────────────────────────────────
    82→
    83→  /** The current conversation stage. */
    84→  get currentStage(): ConversationStage { return this._currentStage; }
    85→
    86→  /** The previous conversation stage, or null if still in the first stage. */
    87→  get previousStage(): ConversationStage | null { return this._previousStage; }
    88→
    89→  /** Ordered list of every stage visited (may include re-visits). */
    90→  get stageHistory(): readonly ConversationStage[] { return this._stageHistory; }
    91→
    92→  /** Immutable audit log of every transition. */
    93→  get transitionLog(): readonly TransitionRecord[] { return this._transitionLog; }
    94→
    95→  /** True if the machine is in a terminal stage. */
    96→  get isTerminal(): boolean { return isTerminalStage(this._currentStage); }
    97→
    98→  /**
    99→   * Returns a frozen snapshot of the current state.
   100→   */
   101→  getState(now: number = Date.now()): ConversationState {
   102→    return new ConversationState({
   103→      currentStage: this._currentStage,
   104→      previousStage: this._previousStage,
   105→      stageHistory: [...this._stageHistory],
   106→      stageEnteredAt: this._stageEnteredAt,
   107→      snapshotAt: now,
   108→      memory: this._memory,
   109→      progress: this._progress,
   110→    });
   111→  }
   112→
   113→  /**
   114→   * Dispatches a signal to the state machine.
   115→   *
   116→   * The machine:
   117→   * 1. Updates progress/memory from the signal payload.
   118→   * 2. Determines whether a stage transition is needed.
   119→   * 3. Validates and applies the transition.
   120→   * 4. Returns the new state snapshot.
   121→   *
   122→   * @throws {TransitionError} if a ForceStageSignal targets an invalid stage.
   123→   */
   124→  dispatch(signal: ConversationSignal, now: number = Date.now()): ConversationState {
   125→    // Apply side effects from the signal to memory and progress
   126→    this._applySignalSideEffects(signal, now);
   127→
   128→    // Determine if the signal requests a stage transition
   129→    const targetStage = this._resolveTargetStage(signal);
   130→    if (targetStage !== null) {
   131→      this._transition(targetStage, signal, now);
   132→    }
   133→
   134→    return this.getState(now);
   135→  }
   136→
   137→  /**
   138→   * Attempts to transition to a specific stage.
   139→   * Returns true if the transition succeeded, false if rejected.
   140→   */
   141→  tryTransitionTo(
   142→    stage: ConversationStage,
   143→    signal: ConversationSignal,
   144→    now: number = Date.now()
   145→  ): boolean {
   146→    if (!isTransitionAllowed(this._currentStage, stage)) return false;
   147→    this._transition(stage, signal, now);
   148→    return true;
   149→  }
   150→
   151→  // ─── Signal Side Effects ────────────────────────────────────────────────────
   152→
   153→  private _applySignalSideEffects(signal: ConversationSignal, _now: number): void {
   154→    switch (signal.type) {
   155→      case 'AGENT_TURN_COMPLETED':
   156→        this._progress.recordAgentTurn(this._currentStage);
   157→        if (signal.containedQuestion) {
   158→          this._progress.recordQuestion(this._currentStage);
   159→        }
   160→        break;
   161→
   162→      case 'QUESTION_ASKED':
   163→        this._progress.recordQuestion(this._currentStage);
   164→        break;
   165→
   166→      case 'CUSTOMER_INTERRUPTED':
   167→        this._progress.recordInterruption(this._currentStage);
   168→        break;
   169→
   170→      case 'OBJECTION_RAISED':
