   234→    if (isTerminalStage(this._currentStage)) {
   235→      // Silently ignore — terminal stages never transition
   236→      return;
   237→    }
   238→
   239→    // CALL_COMPLETED is always reachable as an emergency exit
   240→    if (to !== ConversationStage.CALL_COMPLETED && !isTransitionAllowed(this._currentStage, to)) {
   241→      throw new TransitionError(
