   249→      from: this._currentStage,
   250→      to,
   251→      signal,
   252→      occurredAt: now,
   253→    };
   254→
   255→    this._progress.exitStage(this._currentStage, now);
   256→    this._previousStage = this._currentStage;
   257→    this._currentStage = to;
   258→    this._stageHistory.push(to);
   259→    this._stageEnteredAt = now;
   260→    this._transitionLog.push(record);
   261→    this._progress.enterStage(to, now);
   262→  }
   263→
   264→  // ─── Funnel Advancement ─────────────────────────────────────────────────────
   265→
   266→  /**
   267→   * Returns the next stage in the canonical funnel order, or
   268→   * CALL_COMPLETED if we are at the end.
   269→   */
   270→  private _nextFunnelStage(): ConversationStage {
   271→    const currentIndex = FUNNEL_ORDER.indexOf(this._currentStage);
   272→    if (currentIndex === -1 || currentIndex >= FUNNEL_ORDER.length - 1) {
   273→      return ConversationStage.CALL_COMPLETED;
   274→    }
   275→    // Find the next stage in the funnel that is actually allowed
   276→    for (let i = currentIndex + 1; i < FUNNEL_ORDER.length; i++) {
   277→      const candidate = FUNNEL_ORDER[i];
   278→      if (isTransitionAllowed(this._currentStage, candidate)) {
   279→        return candidate;
   280→      }
   281→    }
   282→    return ConversationStage.CALL_COMPLETED;
   283→  }
