    22→ * `evaluate()` is deterministic given the same state.
    23→ */
    24→
    25→import { ConversationStage, STAGE_METADATA } from './ConversationStage.js';
    26→import type { ConversationState } from './ConversationState.js';
    27→
    28→// ─── Agent Action Types ───────────────────────────────────────────────────────
    29→
    30→export type AgentActionType =
    31→  | 'ASK_QUESTION'
    32→  | 'EXPLAIN'
    33→  | 'SUMMARIZE'
    34→  | 'HANDLE_OBJECTION'
    35→  | 'ATTEMPT_CLOSE'
    36→  | 'ADVANCE_STAGE'
    37→  | 'RE_ENGAGE'    // customer silent / disengaged
    38→  | 'WRAP_UP';     // call about to complete
    39→
    40→/**
    41→ * A structured recommendation produced by the evaluator.
    42→ */
    43→export interface AgentAction {
    44→  /** The recommended next action type. */
    45→  readonly action: AgentActionType;
    46→  /** Confidence level for this recommendation (0–1). */
    47→  readonly confidence: number;
    48→  /** Human-readable rationale for the recommendation. */
    49→  readonly rationale: string;
    50→  /** Whether the state machine should advance stage after this action. */
    51→  readonly shouldAdvanceStage: boolean;
    52→}
    53→
    54→// ─── Evaluation Config ────────────────────────────────────────────────────────
    55→
    56→export interface EvaluatorConfig {
    57→  /**
    58→   * Maximum questions to ask in a single stage before forcing an advance.
    59→   * @default 4
    60→   */
    61→  maxQuestionsPerStage: number;
    62→  /**
    63→   * Maximum milliseconds to spend in a single stage before forcing an advance.
    64→   * @default 120_000 (2 minutes)
    65→   */
    66→  maxMsPerStage: number;
    67→  /**
    68→   * Minimum pain points needed before PRESENTATION is allowed.
    69→   * @default 1
    70→   */
    71→  minPainPointsForPresentation: number;
    72→}
    73→
    74→export const DEFAULT_EVALUATOR_CONFIG: Readonly<EvaluatorConfig> = {
    75→  maxQuestionsPerStage: 4,
    76→  maxMsPerStage: 120_000,
    77→  minPainPointsForPresentation: 1,
    78→};
    79→
    80→// ─── ConversationEvaluator ────────────────────────────────────────────────────
    81→
    82→export class ConversationEvaluator {
    83→  private readonly config: Readonly<EvaluatorConfig>;
    84→
    85→  constructor(config: Partial<EvaluatorConfig> = {}) {
    86→    this.config = Object.freeze({ ...DEFAULT_EVALUATOR_CONFIG, ...config });
    87→  }
    88→
    89→  /**
    90→   * Evaluates the current conversation state and returns a recommended action.
    91→   * Pure — no mutations, no async.
    92→   */
    93→  evaluate(state: ConversationState, now: number = Date.now()): AgentAction {
    94→    // ── Terminal — wrap up ────────────────────────────────────────────────────
    95→    if (state.isTerminal) {
    96→      return this._action('WRAP_UP', 1, 'Conversation is in a terminal stage.', false);
    97→    }
    98→
    99→    // ── Unresolved objection — must handle before anything else ───────────────
   100→    if (state.hasUnresolvedObjections && state.currentStage !== ConversationStage.OBJECTION_HANDLING) {
   101→      return this._action(
   102→        'HANDLE_OBJECTION',
   103→        0.95,
   104→        `There are ${state.memory.unresolvedObjections.length} unresolved objection(s). Transition to objection handling.`,
   105→        true
   106→      );
   107→    }
   108→
   109→    const timeInStage = state.timeInCurrentStage(now);
   110→    const questionsInStage = state.questionsInCurrentStage;
   111→    const minTurns = STAGE_METADATA[state.currentStage].minTurns;
   112→
   113→    // ── Stage-specific evaluation ─────────────────────────────────────────────
   114→    switch (state.currentStage) {
   115→      case ConversationStage.GREETING:
   116→        return this._evaluateGreeting(state);
   117→
   118→      case ConversationStage.RAPPORT:
   119→        return this._evaluateRapport(state, timeInStage, questionsInStage);
   120→
   121→      case ConversationStage.DISCOVERY:
   122→        return this._evaluateDiscovery(state, questionsInStage);
   123→
   124→      case ConversationStage.QUALIFICATION:
   125→        return this._evaluateQualification(state, questionsInStage);
   126→
   127→      case ConversationStage.PRESENTATION:
   128→        return this._evaluatePresentation(state, questionsInStage);
   129→
   130→      case ConversationStage.OBJECTION_HANDLING:
   131→        return this._evaluateObjectionHandling(state);
   132→
   133→      case ConversationStage.CLOSING:
   134→        return this._evaluateClosing(state);
   135→
   136→      case ConversationStage.CALL_COMPLETED:
   137→        return this._action('WRAP_UP', 1, 'Call is complete.', false);
   138→    }
   139→
   140→    // Exhaustive default
   141→    return this._action('ASK_QUESTION', 0.5, 'Unknown stage — default to asking a question.', false);
   142→  }
   143→
   144→  // ─── Stage Evaluators ──────────────────────────────────────────────────────
   145→
   146→  private _evaluateGreeting(state: ConversationState): AgentAction {
   147→    if (state.turnsInCurrentStage === 0) {
   148→      return this._action('ASK_QUESTION', 1, 'No turns yet — open with greeting and ice-breaker question.', false);
   149→    }
   150→    if (state.hasMetMinimumTurns) {
   151→      return this._action('ADVANCE_STAGE', 0.9, 'Greeting complete — advance to rapport.', true);
   152→    }
   153→    return this._action('ASK_QUESTION', 0.8, 'Continue greeting — minimum turns not yet met.', false);
   154→  }
   155→
   156→  private _evaluateRapport(
   157→    state: ConversationState,
   158→    timeInStage: number,
   159→    questionsInStage: number
   160→  ): AgentAction {
   161→    if (questionsInStage >= 2 || timeInStage > 30_000) {
   162→      return this._action('ADVANCE_STAGE', 0.85, 'Rapport established — transition to discovery.', true);
   163→    }
   164→    return this._action('ASK_QUESTION', 0.9, 'Build rapport with an open question about the customer.', false);
   165→  }
   166→
   167→  private _evaluateDiscovery(
   168→    state: ConversationState,
   169→    questionsInStage: number
   170→  ): AgentAction {
   171→    const painPoints = state.memory.painPoints.length;
   172→    const atLimit = questionsInStage >= this.config.maxQuestionsPerStage;
   173→
   174→    if (painPoints >= this.config.minPainPointsForPresentation && state.hasMetMinimumTurns) {
   175→      return this._action('ADVANCE_STAGE', 0.88, `${painPoints} pain point(s) found — ready for qualification.`, true);
   176→    }
   177→    if (atLimit) {
   178→      return this._action(
   179→        'SUMMARIZE',
   180→        0.75,
   181→        'Question limit reached in discovery — summarise findings before advancing.',
   182→        true
   183→      );
   184→    }
   185→    return this._action('ASK_QUESTION', 0.92, 'Continue discovering pain points.', false);
   186→  }
   187→
   188→  private _evaluateQualification(
   189→    state: ConversationState,
   190→    questionsInStage: number
   191→  ): AgentAction {
   192→    const { budget, timeline, isDecisionMaker } = state.memory;
   193→    const qualified = budget !== undefined && timeline !== undefined && isDecisionMaker !== undefined;
   194→    const atLimit = questionsInStage >= this.config.maxQuestionsPerStage;
   195→
   196→    if (qualified) {
   197→      return this._action('ADVANCE_STAGE', 0.9, 'All qualification data gathered — advance to presentation.', true);
   198→    }
   199→    if (atLimit) {
   200→      return this._action(
   201→        'SUMMARIZE',
   202→        0.7,
   203→        'Question limit reached in qualification — advance with partial data.',
   204→        true
   205→      );
   206→    }
   207→    // Determine which field to qualify next
   208→    if (isDecisionMaker === undefined) {
   209→      return this._action('ASK_QUESTION', 0.95, 'Decision-maker not confirmed — ask about authority.', false);
   210→    }
   211→    if (budget === undefined) {
   212→      return this._action('ASK_QUESTION', 0.9, 'Budget not captured — ask about investment capacity.', false);
   213→    }
   214→    return this._action('ASK_QUESTION', 0.85, 'Timeline not captured — ask about urgency.', false);
   215→  }
   216→
   217→  private _evaluatePresentation(
   218→    state: ConversationState,
   219→    questionsInStage: number
   220→  ): AgentAction {
   221→    if (state.turnsInCurrentStage === 0) {
   222→      return this._action('EXPLAIN', 0.95, 'Present the solution tied to the discovered pain.', false);
   223→    }
   224→    if (questionsInStage >= 1 && state.hasMetMinimumTurns) {
   225→      return this._action('ATTEMPT_CLOSE', 0.8, 'Presentation delivered and reaction gauged — attempt close.', true);
   226→    }
   227→    return this._action('ASK_QUESTION', 0.85, 'Check reaction to presentation with a probing question.', false);
   228→  }
   229→
   230→  private _evaluateObjectionHandling(state: ConversationState): AgentAction {
   231→    const unresolved = state.memory.unresolvedObjections;
   232→    if (unresolved.length === 0) {
   233→      return this._action('ADVANCE_STAGE', 0.9, 'All objections resolved — return to funnel.', true);
   234→    }
   235→    if (state.turnsInCurrentStage === 0) {
   236→      return this._action('EXPLAIN', 0.95, `Address objection: "${unresolved[0].topic}".`, false);
   237→    }
   238→    return this._action('ASK_QUESTION', 0.8, 'Check whether the objection has been resolved to the customer\'s satisfaction.', false);
   239→  }
   240→
   241→  private _evaluateClosing(state: ConversationState): AgentAction {
   242→    if (!state.memory.hasNextAction) {
   243→      return this._action('SUMMARIZE', 0.9, 'Summarise conversation and propose a concrete next step.', false);
   244→    }
   245→    if (state.memory.commitments.length > 0) {
   246→      return this._action('WRAP_UP', 0.95, 'Commitment made and next action confirmed — wrap up gracefully.', true);
   247→    }
   248→    return this._action('ATTEMPT_CLOSE', 0.85, 'Next action set but commitment not yet confirmed — solidify.', false);
   249→  }
   250→
   251→  // ─── Helpers ────────────────────────────────────────────────────────────────
   252→
   253→  private _action(
   254→    action: AgentActionType,
   255→    confidence: number,
   256→    rationale: string,
   257→    shouldAdvanceStage: boolean
   258→  ): AgentAction {
   259→    return Object.freeze({ action, confidence, rationale, shouldAdvanceStage });
   260→  }
   261→}
