     1→/**
     2→ * @module ConversationProgress
     3→ *
     4→ * Tracks quantitative progress metrics for the current conversation.
     5→ *
     6→ * ## Purpose
     7→ * Maintains per-stage and overall counters — agent turns, questions asked,
     8→ * interruptions, and time spent — so the evaluator and state machine can
     9→ * make data-driven decisions (e.g. "has the minimum turn count been met?").
    10→ *
    11→ * ## Ownership
    12→ * Created alongside `ConversationState` and mutated by the state machine
    13→ * as turns arrive.  Read-only outside the state machine.
    14→ *
    15→ * ## No AI imports
    16→ * Pure metrics container — no OpenAI, Exotel, or prompt logic.
    17→ */
    18→
    19→import type { ConversationStage } from './ConversationStage.js';
    20→
    21→// ─── Per-Stage Stats ──────────────────────────────────────────────────────────
    22→
    23→export interface StageStats {
    24→  /** Number of completed agent turns in this stage. */
    25→  agentTurns: number;
    26→  /** Number of questions the agent asked in this stage. */
    27→  questionsAsked: number;
    28→  /** Number of times the customer interrupted the agent in this stage. */
    29→  interruptions: number;
    30→  /** Epoch ms when this stage was entered. */
    31→  enteredAt: number;
    32→  /** Epoch ms when this stage was exited, or null if still active. */
    33→  exitedAt: number | null;
    34→}
    35→
    36→// ─── ConversationProgress ─────────────────────────────────────────────────────
    37→
    38→export class ConversationProgress {
    39→  private readonly _stageStats: Map<ConversationStage, StageStats> = new Map();
    40→
    41→  /** Wall-clock epoch ms when the entire conversation started. */
    42→  readonly conversationStartedAt: number;
    43→
    44→  /** Total agent turns across all stages. */
    45→  private _totalAgentTurns = 0;
    46→
    47→  /** Total questions asked across all stages. */
