    60→   * Records entry into a stage — initialises its stats block.
    61→   * Safe to call multiple times for the same stage (re-entry after objection
    62→   * handling will accumulate rather than reset).
    63→   */
    64→  enterStage(stage: ConversationStage, now: number = Date.now()): void {
    65→    if (!this._stageStats.has(stage)) {
    66→      this._stageStats.set(stage, {
    67→        agentTurns: 0,
    68→        questionsAsked: 0,
    69→        interruptions: 0,
    70→        enteredAt: now,
    71→        exitedAt: null,
    72→      });
    73→    }
    74→  }
