   119→  get totalInterruptions(): number { return this._totalInterruptions; }
   120→
   121→  /**
   122→   * Stats for a specific stage, or null if that stage has not been entered.
   123→   */
   124→  getStageStats(stage: ConversationStage): Readonly<StageStats> | null {
   125→    return this._stageStats.get(stage) ?? null;
   126→  }
   127→
   128→  /**
   129→   * Number of completed agent turns in a specific stage.
   130→   */
   131→  turnsInStage(stage: ConversationStage): number {
   132→    return this._stageStats.get(stage)?.agentTurns ?? 0;
   133→  }
   134→
   135→  /**
   136→   * Number of questions asked in a specific stage.
   137→   */
   138→  questionsInStage(stage: ConversationStage): number {
   139→    return this._stageStats.get(stage)?.questionsAsked ?? 0;
   140→  }
   141→
   142→  /**
   143→   * Milliseconds elapsed in a specific stage.
   144→   * Returns elapsed-to-now if the stage has not yet exited.
   145→   */
   146→  timeInStage(stage: ConversationStage, now: number = Date.now()): number {
   147→    const stats = this._stageStats.get(stage);
   148→    if (!stats) return 0;
   149→    return (stats.exitedAt ?? now) - stats.enteredAt;
   150→  }
   151→
   152→  /**
   153→   * Total elapsed milliseconds since the conversation started.
   154→   */
   155→  totalElapsedMs(now: number = Date.now()): number {
   156→    return now - this.conversationStartedAt;
   157→  }
   158→
   159→  /**
   160→   * Ordered list of stages that have been entered (in entry order).
   161→   */
   162→  get visitedStages(): readonly ConversationStage[] {
   163→    return Array.from(this._stageStats.keys());
   164→  }
   165→
   166→  /**
   167→   * Serialises all progress metrics to a plain object for logging.
   168→   */
   169→  toSnapshot(now: number = Date.now()): Readonly<Record<string, unknown>> {
   170→    const stageBreakdown: Record<string, unknown> = {};
   171→    for (const [stage, stats] of Array.from(this._stageStats)) {
   172→      stageBreakdown[stage] = {
   173→        ...stats,
   174→        elapsedMs: (stats.exitedAt ?? now) - stats.enteredAt,
   175→      };
   176→    }
   177→    return Object.freeze({
   178→      conversationStartedAt: this.conversationStartedAt,
   179→      totalElapsedMs: this.totalElapsedMs(now),
   180→      totalAgentTurns: this._totalAgentTurns,
   181→      totalQuestionsAsked: this._totalQuestionsAsked,
   182→      totalInterruptions: this._totalInterruptions,
   183→      stages: stageBreakdown,
   184→    });
   185→  }
   186→
   187→  // ─── Private Helpers ────────────────────────────────────────────────────────
   188→
   189→  private _ensureStage(stage: ConversationStage): StageStats {
   190→    if (!this._stageStats.has(stage)) {
   191→      this.enterStage(stage);
   192→    }
   193→    return this._stageStats.get(stage)!;
   194→  }
   195→}
